+test "TF_DS_CACHE_REPLACE_STALE: a stale full end is replaced at its own keep, and a live one is never copied again" {
+    const gpa = std.testing.allocator;
+    var f: Fake = .{ .gpa = gpa };
+    var s = Store.init(gpa, f.snapshots(), .{ .min_prompt = 0, .endstate = true }, 1 << 20);
+    defer s.deinit();
+    s.replace_stale = true;
+    const t1 = [_]u32{ 1, 2, 3, 4, 5 };
+    f.at = 5;
+    f.sum = fresh(&t1);
+    try std.testing.expect(s.keep(&t1, 5, null, &.{})); // the pass's own end (at == len)
