+    try std.testing.expectEqual(@as(usize, 1), s.entries.items.len);
+    try std.testing.expect(s.entries.items[0].full_end);
+    f.stale = null;
+    try std.testing.expect(s.keep(&t1, 5, null, &.{})); // live again: refreshed, never copied again
