//! TF_DS_CACHE_REPLACE_STALE (off by default): keeping a state the prompt cache already holds replaces a stale
//! duplicate instead of refreshing it (upstream PR #134's keep side). Pure: no cuda import; the switch is read at
//! each prompt-cache store's construction (`Store.replace_stale`) and `keepWith`'s duplicate arm consults `probeLen`
//! for the family's staleness probe. A malformed switch refuses startup. Off: every keep refreshes a duplicate
//! exactly as before.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_CACHE_REPLACE_STALE";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadCacheReplaceStale}!bool {
    return parse(text) orelse error.BadCacheReplaceStale;
}

/// The prompt length the stale-duplicate arm passes the family's `usable`: staleness only, never the keeping
/// prompt's length, so a valid state near the prompt end is never copied again. An end state restores at exactly
/// its own length (`Lanes.usable` answers `is_end` there), so its staleness shows at `at`; every other state's does
/// at the longest prompt (the family's length gates all pass there).
pub fn probeLen(full_end: bool, at: u32) u32 {
    return if (full_end) at else std.math.maxInt(u32);
}

test "TF_DS_CACHE_REPLACE_STALE: 1 turns it on, unset/\"\"/0 turn it off, anything else refuses" {
    try std.testing.expectEqual(@as(?bool, false), parse(null));
    try std.testing.expectEqual(@as(?bool, false), parse(""));
    try std.testing.expectEqual(@as(?bool, false), parse("0"));
    try std.testing.expectEqual(@as(?bool, true), parse("1"));
    for ([_][]const u8{ "2", "on", "true", " 1", "1 " }) |bad| {
        try std.testing.expectEqual(@as(?bool, null), parse(bad));
        try std.testing.expectError(error.BadCacheReplaceStale, fromText(bad));
    }
    try std.testing.expectEqual(@as(?bool, true), try fromText("1"));
}

test "probeLen: an end state probes at its own length, any other state at the longest" {
    try std.testing.expectEqual(@as(u32, 4096), probeLen(true, 4096));
    try std.testing.expectEqual(std.math.maxInt(u32), probeLen(false, 4096));
}

