    /// A looked-up entry's restore went through (it is now the prompt's), or failed (dropped: the pass ran from 0).
    pub fn resumed(s: *Store, e: *Entry, prompt: []const u32, ok: bool) void {
        const i = std.mem.indexOfScalar(*Entry, s.entries.items, e) orelse return;
        if (!ok) {
            s.counts.failed += 1;
            if (s.metrics) s.counts.failed_restore += 1;
            return s.remove(i);
        }
        s.clock += 1;
        e.used = s.clock;
        s.counts.hits += 1;
        if (e.point) |p| if (s.tier) |t| if (t.vtable.touch) |f| f(t.ptr, p);
        const last = s.gpa.dupe(u32, prompt) catch return;
        s.gpa.free(e.last);
        e.last = last;
    }

    /// Where a pass from `from` keeps states: the history, then min_gap apart the stable prefix and shared blocks.
    pub fn marks(s: *const Store, a: Allocator, prompt: []const u32, from: u32, history_len: u32, shared: []const u32, starts: []const u32, previous: []const u32) ![]const u32 {
        if (prompt.len < s.rules.min_prompt) return &.{};
        var out: std.ArrayList(u32) = .empty;
        var want: std.ArrayList(u32) = .empty;
        defer want.deinit(a);
        try want.append(a, history_len);
        if (previous.len > 0) {
            const stable: u32 = @intCast(std.mem.indexOfDiff(u32, previous, prompt) orelse @min(previous.len, prompt.len));
            const keeps = if (s.rules.edit_mark) stable >= from + s.rules.min_gap and stable >= s.rules.min_prompt / 4 else stable >= history_len / 2;
            if (stable > 0 and stable < history_len and keeps) try want.append(a, stable);
        }
        try want.appendSlice(a, shared);
        // TF_DS_EXACT_RESUME: the pass's own end, off the grid (rounded down to even: dsv41's ratio-2 layers refuse an odd
        // start), which the next turn resumes from on its tail's rows; no gap rule applies to it
        if (s.rules.exact and prompt.len >= 2) {
            const end: u32 = @intCast(prompt.len & ~@as(usize, 1));
            if (end > from and std.mem.indexOfScalar(u32, out.items, end) == null) try out.append(a, end);
        }
        for (want.items, 0..) |w, k| {
            const at = if (s.rules.planned) floorStart(starts, w) else w;
            if (at <= from or at + s.rules.lookahead > prompt.len or at >= prompt.len or !s.usable(at, starts)) continue;
            if (k > 0) { // the history's mark always; the others only away from it, each other and the resume point
                if (at - from < s.rules.min_gap) continue;
                const near = for (out.items) |o| {
                    if (@max(o, at) - @min(o, at) < s.rules.min_gap) break true;
                } else false;
                if (near) continue;
            }
            if (std.mem.indexOfScalar(u32, out.items, at) == null) try out.append(a, at);
        }
        std.mem.sort(u32, out.items, {}, std.sort.asc(u32));
        return out.toOwnedSlice(a);
    }

    /// The prompt pass stands at `at`: keep its state for `prompt`, evicting to fit; refused (counted) past the budget.
    pub fn keep(s: *Store, prompt: []const u32, at: u32, owner: ?*anyopaque, starts: []const u32) bool {
        return s.keepWith(prompt, at, owner, starts, .{});
    }

    /// keep, recording the state's conversation, pictures and lineage; with a tier its write is enqueued here.
    pub fn keepWith(s: *Store, prompt: []const u32, at: u32, owner: ?*anyopaque, starts: []const u32, info: KeepInfo) bool {
        const n = @as(usize, at) + s.rules.lookahead;
        if (at == 0 or n > prompt.len) return false;
        s.clock += 1;
        const shared = if (s.shared_plan) info.shared else std.mem.indexOfScalar(u64, s.shared_keys.items, sharedKey(prompt[0..n])) != null;
        const full_end = s.rules.endstate and at == prompt.len;
        for (s.entries.items, 0..) |e, i| if (e.at == at and std.mem.eql(u32, e.tokens, prompt[0..n])) {
            if (full_end and !e.full_end) {
                s.remove(i);
                break;
            }
            // TF_DS_CACHE_REPLACE_STALE: the same state again, but the family let it go (stale): it restores for no
            // prompt now, so a fresh copy replaces the dead one instead of refreshing it. The probe is staleness only
            // (probeLen), never this prompt's length, so a valid state near the prompt end is never copied again; a
            // durable point is left alone (the tier's restore replaces its stale twin in `adopt`).
            if (s.replace_stale and e.point == null) if (s.family.vtable.usable) |f| {
                if (!f(s.family.ptr, e.saved, cache_replace_stale.probeLen(e.full_end, e.at))) {
                    if (!@import("builtin").is_test and !replace_stale_noted.swap(true, .monotonic)) std.log.info("dsv41: TF_DS_CACHE_REPLACE_STALE: a stale kept state is replaced by its fresh copy (first at {d} tokens)", .{at});
                    s.remove(i);
                    break;
                }
            };
            e.used = s.clock; // the same state again: no copy
            if (shared and !e.shared) { // now a shared prefix: the family's copy marked, and on disk
